with flattened_attrs as (select id, level, payload_json, coalesce(context['region'], 'none') as region_or_default, coalesce(context['version'], 'none') as version_or_default, context['region'] as region, array_contains(map_keys(context), 'version') as has_version, cast((status_code & 1) != 0 as int) as is_flagged from app_logs where level = 'INFO') select id, region, lag(is_flagged, 1, 0) over (partition by level order by is_flagged asc, id asc) as prev_is_flagged, last_value(region) ignore nulls over w_ordered as last_known_region from flattened_attrs where level = 'WARN' window w_ordered as (partition by level order by is_flagged asc, id asc rows between unbounded preceding and current row)
